)) IS DISTINCT FROM '{"policies":[{"cmd":"INSERT","qual":null,"roles":["authenticated"],"permissive":"PERMISSIVE","policyname":"club_private_upload","with_check":"((bucket_id = ''club-chat-private''::text) AND ((club_chat_capabilities() ->> ''attachments''::text))::boolean AND (split_part(name, ''/''::text, 2) = (auth.uid())::text) AND club_chat_has_access(club_chat_path_club(name), auth.uid()))"},{"cmd":"INSERT","qual":null,"roles":["anon","authenticated"],"permissive":"RESTRICTIVE","policyname":"club_private_upload_guard","with_check":"((bucket_id <> ''club-chat-private''::text) OR (((club_chat_capabilities() ->> ''attachments''::text))::boolean AND (split_part(name, ''/''::text, 2) = (auth.uid())::text) AND club_chat_has_access(club_chat_path_club(name), auth.uid())))"}],"functions":{"club_chat_capabilities()":"CREATE OR REPLACE FUNCTION public.club_chat_capabilities()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog''\nAS $function$ SELECT jsonb_build_object(''attachments'',false) $function$\n","club_chat_send_attachment(uuid,uuid,text,text,text,bigint)":"CREATE OR REPLACE FUNCTION public.club_chat_send_attachment(p_club uuid, p_request_id uuid, p_path text, p_kind text, p_name text, p_size bigint)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE uid uuid:=auth.uid(); result uuid; obj jsonb; ext text; expected text;\nBEGIN\n IF uid IS NULL OR NOT COALESCE((public.club_chat_capabilities()->>''attachments'')::boolean,false) OR NOT public.club_chat_has_access(p_club,uid) THEN RAISE EXCEPTION ''club_access_denied'' USING ERRCODE=''42501''; END IF;\n IF p_request_id IS NULL OR p_path IS NULL OR p_kind IS NULL OR p_size IS NULL OR p_name IS NULL THEN RAISE EXCEPTION ''invalid_attachment''; END IF;\n -- Serialize retries of this user''s single request; parallel tabs with different requests remain independent.\n PERFORM pg_advisory_xact_lock(hashtextextended(uid::text||p_request_id::text,0));\n SELECT id INTO result FROM public.club_chat WHERE owner=uid AND attachment_request_id=p_request_id AND club=p_club AND attachment_path=p_path;\n IF result IS NOT NULL THEN RETURN result; END IF;\n ext:=lower(substring(p_path from ''\\.([a-z0-9]+)$''));\n expected:=CASE WHEN ext=ANY(ARRAY[''jpg'',''jpeg'',''png'',''webp'',''gif'']) THEN ''image'' WHEN ext=ANY(ARRAY[''mp3'',''webm'',''ogg'',''mp4'',''m4a'']) THEN ''audio'' WHEN ext=ANY(ARRAY[''pdf'',''doc'',''docx'',''xls'',''xlsx'',''ppt'',''pptx'',''txt'',''zip'']) THEN ''file'' END;\n IF expected IS NULL OR p_kind<>expected OR p_path<>p_club::text||''/''||uid::text||''/''||p_request_id::text||''.''||ext OR length(p_name)>240 OR p_size<1 OR p_size>(CASE WHEN expected=''image'' THEN 10485760 ELSE 26214400 END) THEN RAISE EXCEPTION ''invalid_attachment''; END IF;\n SELECT metadata INTO obj FROM storage.objects WHERE bucket_id=''club-chat-private'' AND name=p_path;\n IF obj IS NULL OR (obj->>''size'') IS NULL OR (obj->>''size'')::bigint<>p_size THEN RAISE EXCEPTION ''attachment_not_uploaded''; END IF;\n INSERT INTO public.club_chat(club,owner,text,img,attachment_path,attachment_type,attachment_name,attachment_size,attachment_request_id)\n VALUES(p_club,uid,NULL,ARRAY[]::text[],p_path,p_kind,p_name,p_size,p_request_id) RETURNING id INTO result;\n RETURN result;\nEND;$function$\n"}}'::jsonb THEN RAISE EXCEPTION 'baseline_mismatch'; END IF; END $check$;
CREATE TEMP TABLE mg_club_scope_before ON COMMIT DROP AS SELECT jsonb_build_object(
 'policies',(SELECT jsonb_agg(to_jsonb(x) ORDER BY schemaname,tablename,policyname) FROM pg_policies x WHERE (schemaname='storage' OR (schemaname='public' AND tablename IN ('club_chat','club_posts','club_subs','clubs'))) AND NOT(schemaname='storage' AND tablename='objects' AND policyname IN ('club_private_upload','club_private_upload_guard'))),
 'bucket',(SELECT to_jsonb(b) FROM storage.buckets b WHERE id='club-chat-private'),
 'access',(SELECT jsonb_object_agg(p.proname,pg_get_functiondef(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('club_chat_has_access','club_chat_path_club')),
 'push',(SELECT jsonb_object_agg(tgname,tgenabled) FROM pg_trigger WHERE tgname IN ('trg_push_web_club_message','trg_push_web_club_post')),
 'rls',(SELECT jsonb_object_agg(oid::regclass::text,jsonb_build_array(relrowsecurity,relforcerowsecurity)) FROM pg_class WHERE oid IN ('public.club_chat'::regclass,'public.club_posts'::regclass,'public.club_subs'::regclass,'storage.objects'::regclass)),
 'acl',(SELECT jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('owner',p.proowner,'acl',p.proacl)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('club_chat_send_attachment','club_chat_has_access','club_chat_path_club'))
) AS state;
-- PREPARATION ONLY. Install in one transaction with approved Storage changes.
CREATE OR REPLACE FUNCTION public.club_chat_capabilities(p_club uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('attachments',COALESCE(
 p_club=NULL::uuid AND public.club_chat_has_access(p_club,auth.uid()),false))
$$;
REVOKE ALL ON FUNCTION public.club_chat_capabilities(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.club_chat_capabilities(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.club_chat_send_attachment(p_club uuid,p_request_id uuid,p_path text,p_kind text,p_name text,p_size bigint)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE uid uuid:=auth.uid(); result uuid; obj jsonb; ext text; expected text;
BEGIN
 IF uid IS NULL OR NOT COALESCE((public.club_chat_capabilities(p_club)->>'attachments')::boolean,false) OR NOT public.club_chat_has_access(p_club,uid) THEN RAISE EXCEPTION 'club_access_denied' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR p_path IS NULL OR p_kind IS NULL OR p_size IS NULL OR p_name IS NULL THEN RAISE EXCEPTION 'invalid_attachment'; END IF;
 -- Serialize retries of this user's single request; parallel tabs with different requests remain independent.
 PERFORM pg_advisory_xact_lock(hashtextextended(uid::text||p_request_id::text,0));
 SELECT id INTO result FROM public.club_chat WHERE owner=uid AND attachment_request_id=p_request_id AND club=p_club AND attachment_path=p_path;
 IF result IS NOT NULL THEN RETURN result; END IF;
 ext:=lower(substring(p_path from '\.([a-z0-9]+)$'));
 expected:=CASE WHEN ext=ANY(ARRAY['jpg','jpeg','png','webp','gif']) THEN 'image' WHEN ext=ANY(ARRAY['mp3','webm','ogg','mp4','m4a']) THEN 'audio' WHEN ext=ANY(ARRAY['pdf','doc','docx','xls','xlsx','ppt','pptx','txt','zip']) THEN 'file' END;
 IF expected IS NULL OR p_kind<>expected OR p_path<>p_club::text||'/'||uid::text||'/'||p_request_id::text||'.'||ext OR length(p_name)>240 OR p_size<1 OR p_size>(CASE WHEN expected='image' THEN 10485760 ELSE 26214400 END) THEN RAISE EXCEPTION 'invalid_attachment'; END IF;
 SELECT metadata INTO obj FROM storage.objects WHERE bucket_id='club-chat-private' AND name=p_path;
 IF obj IS NULL OR (obj->>'size') IS NULL OR (obj->>'size')::bigint<>p_size THEN RAISE EXCEPTION 'attachment_not_uploaded'; END IF;
 INSERT INTO public.club_chat(club,owner,text,img,attachment_path,attachment_type,attachment_name,attachment_size,attachment_request_id)
 VALUES(p_club,uid,NULL,ARRAY[]::text[],p_path,p_kind,p_name,p_size,p_request_id) RETURNING id INTO result;
 RETURN result;
END;$$;
-- NOT AUTHORIZED: two existing INSERT policy expressions only. No read/update/delete or membership changes.
ALTER POLICY club_private_upload ON storage.objects WITH CHECK(
 bucket_id='club-chat-private' AND (public.club_chat_capabilities(public.club_chat_path_club(name))->>'attachments')::boolean
 AND split_part(name,'/',2)=auth.uid()::text AND public.club_chat_has_access(public.club_chat_path_club(name),auth.uid()));
ALTER POLICY club_private_upload_guard ON storage.objects WITH CHECK(
 bucket_id<>'club-chat-private' OR ((public.club_chat_capabilities(public.club_chat_path_club(name))->>'attachments')::boolean AND split_part(name,'/',2)=auth.uid()::text AND public.club_chat_has_access(public.club_chat_path_club(name),auth.uid())));

